import ctypes, os
import numpy as np
_lib = ctypes.CDLL(os.path.join(os.path.dirname(os.path.abspath(__file__)), "libemd.so"))
_lib.solve.restype = ctypes.c_int
_lib.solve.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_double, ctypes.c_void_p]


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        if M.shape == (n, n) and n > 0 and np.all(a == a[0]) and np.all(b == a[0]):
            col = np.empty(n, dtype=np.int32)
            if _lib.solve(n, M.ctypes.data, 30.0, col.ctypes.data) == 0:
                G = np.zeros((n, n))
                G[np.arange(n), col] = a[0]
                return {"transport_plan": G}
        import ot
        return {"transport_plan": ot.lp.emd(a, b, M, check_marginals=False)}

